// Extract embedding from Ollama response
// Handles multiple response formats across Ollama versions
let emb = null;
if (Array.isArray($json?.data) && $json.data[0]?.embedding) {
  emb = $json.data[0].embedding;
} else if (Array.isArray($json?.embedding)) {
  emb = $json.embedding;
} else if (Array.isArray($json?.response?.embedding)) {
  emb = $json.response.embedding;
}
if (!emb) {
  throw new Error("Could not find embedding in Ollama response. If your Ollama version expects `input` instead of `prompt`, update the request body in the Ollama node.");
}
return [{ json: { embedding: emb } }];

// Build Pinecone query body
// topK=150 balances recall vs latency. Increase for broader queries, decrease for speed.

const embedding = $json.embedding;
if (!Array.isArray(embedding)) throw new Error("Missing embedding");

const uniq = (a) => Array.from(new Set(a));
const normJoin = (s) => String(s).trim().replace(/\s+/g, '').replace(/-/g, '');
function codeVariants(code) {
  const raw = String(code).trim();
  const joined = normJoin(raw);
  if (!raw) return [];
  return uniq([raw, joined, joined.toUpperCase(), joined.toLowerCase()]);
}

const brandsIn = Array.isArray($json.brands) ? $json.brands.filter(Boolean) : [];
const codesIn  = Array.isArray($json.codes)  ? $json.codes.filter(Boolean)  : [];
const codesAll = uniq(codesIn.flatMap(codeVariants).filter(Boolean));

const CODE_FIELDS = [
  "ProdNo","prodno","ProductID","ProductId","ProductCode",
  "SKU","Sku","Style","StyleNo","StyleNumber",
  "ItemNo","ItemNumber","Model","ModelNo"
];

const topK = 150;

const pineconeBody = {
  vector: embedding,
  topK,
  includeValues: false,
  includeMetadata: true,
  namespace: ""
};

if (codesAll.length) {
  const ors = [];
  for (const f of CODE_FIELDS) {
    const clause = {};
    clause[f] = { "$in": codesAll };
    ors.push(clause);
  }
  pineconeBody.filter = { "$or": ors };
}

return [{
  json: {
    ...$json,
    brands: brandsIn,
    codes: codesAll,
    pineconeBody,
    PINECONE_INDEX_HOST: "https://YOUR_INDEX.svc.YOUR_REGION.pinecone.io/query"
  }
}];

/**
 * Query Parser
 *
 * Parses natural language search queries into structured search signals.
 * Handles: fielded filters, tokenization, brand n-gram detection,
 * SKU/code detection, OMIT_UNLESS_ONLY patch, intent family detection.
 *
 * Output fields:
 *   q            - normalized lowercase query
 *   tokens       - search tokens (hat/cap stripped unless only term)
 *   brands       - detected brand names
 *   codes        - detected product codes / SKUs
 *   onlyProdNo   - true if query resolves to a single product code
 *   intentFamilies - detected product category families
 *   categories, titleTerms, descTerms - fielded filter results
 */

function asString(v) { return v == null ? '' : String(v); }
function normalizeSpaces(str) { return asString(str).replace(/\s+/g, ' ').trim(); }
function uniq(arr) {
  var seen = {}; var out = [];
  for (var i = 0; i < arr.length; i++) {
    var k = String(arr[i]);
    if (!seen[k]) { seen[k] = 1; out.push(arr[i]); }
  }
  return out;
}
function escapeRegex(str) { return asString(str).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

// 1) Extract query from multiple possible input shapes
var qRaw = '';
if ($json && $json.q != null) qRaw = asString($json.q);
else if ($json && $json.query && $json.query.q != null) qRaw = asString($json.query.q);
else if ($json && $json.queryString && $json.queryString.q != null) qRaw = asString($json.queryString.q);

var q = normalizeSpaces(qRaw).slice(0, 256);
if (!q) return [{ json: { error: 'Missing q' } }];
q = q.toLowerCase();
var norm = q;

// 2) Fielded filter parsing (category:"foo", title:bar, desc:baz)
function takeField(input, fieldNames, allFieldNames) {
  var out = asString(input); var terms = [];
  var fieldsAlt = fieldNames.map(escapeRegex).join('|');
  var stopAlt = allFieldNames.map(escapeRegex).join('|');
  var re = new RegExp(
    '\\b(?:' + fieldsAlt + ')\\s*:\\s*(?:"([^"]+)"|\'([^\']+)\'|([^\\n\\r]+?))(?=(\\s+\\b(?:' + stopAlt + ')\\b\\s*:)|$)',
    'gi'
  );
  out = out.replace(re, function(_, dq, sq, uq) {
    var v = normalizeSpaces(dq || sq || uq || '');
    if (v) v.split(',').forEach(function(p) { var t = normalizeSpaces(p).toLowerCase(); if (t) terms.push(t); });
    return ' ';
  });
  return [normalizeSpaces(out), uniq(terms)];
}

var s = norm;
var categoryTerms = [], titleTerms = [], descTerms = [];
var ALL_FIELDS = ['category','cat','title','name','desc','description','text'];
var tmp;
tmp = takeField(s, ['category','cat'], ALL_FIELDS); s = tmp[0]; categoryTerms = tmp[1];
tmp = takeField(s, ['title','name'], ALL_FIELDS);    s = tmp[0]; titleTerms    = tmp[1];
tmp = takeField(s, ['desc','description','text'], ALL_FIELDS); s = tmp[0]; descTerms = tmp[1];

// 3) Tokenization
var rawPieces = s.split(/[\s]+/g);
var normalizedTokens = [], skuCandidates = [];
for (var i = 0; i < rawPieces.length; i++) {
  var p = normalizeSpaces(rawPieces[i]);
  if (!p) continue;
  var cand = p.replace(/[^a-z0-9.\-]+/gi, '');
  if (cand && /[a-z]/i.test(cand) && /\d/.test(cand)) skuCandidates.push(cand.toLowerCase());
  var split = p.toLowerCase().split(/[^a-z0-9]+/g);
  for (var j = 0; j < split.length; j++) { if (split[j]) normalizedTokens.push(split[j]); }
}
var tokensAll = uniq(normalizedTokens.filter(Boolean));
var tokens = tokensAll.slice();

// Token gluing: ["st","640"] => "st640"
var glued = [];
for (i = 0; i < tokensAll.length - 1; i++) {
  var a = tokensAll[i], b = tokensAll[i + 1];
  if (/^[a-z]+$/.test(a) && /^[0-9]+[a-z0-9]*$/.test(b)) glued.push(a + b);
}
for (i = 0; i < skuCandidates.length; i++) {
  var squashed = skuCandidates[i].replace(/[.\-]/g, '');
  if (squashed && /^[a-z0-9]+$/i.test(squashed)) glued.push(squashed);
}
tokens = uniq(tokens.concat(glued));
tokensAll = uniq(tokensAll.concat(glued));

// OMIT_UNLESS_ONLY patch:
// Strip 'hat','cap' etc from search tokens when other terms are present.
// Prevents every headwear product matching any multi-word query.
// 'bucket' is exempt — it's a specific product type, not a generic label.
var OMIT_UNLESS_ONLY = { hat:1, hats:1, cap:1, caps:1 };
var tokensBeforeOmit = tokens.slice();
if (tokens.length > 1) {
  var stripped = tokens.filter(function(t) { return !OMIT_UNLESS_ONLY[String(t).toLowerCase()]; });
  tokens = stripped.length ? stripped : tokensBeforeOmit;
}

// 4) Brand detection via token n-grams (supports multi-word brands)
// Add your catalog's brands here
var brandMap = {
  richardson: 'Richardson', yupoong: 'Yupoong',
  bella: 'Bella+Canvas', gildan: 'Gildan', nike: 'Nike',
  carhartt: 'Carhartt', adams: 'Adams', augusta: 'Augusta',
  newera: 'New Era', sporttek: 'Sport-Tek', nextlevel: 'Next Level',
  ogio: 'OGIO', underarmour: 'Under Armour', portauthority: 'Port Authority',
  champion: 'Champion', columbia: 'Columbia'
};
var brandKeyToCanonical = {};
for (var k in brandMap) {
  if (!Object.prototype.hasOwnProperty.call(brandMap, k)) continue;
  brandKeyToCanonical[k.toLowerCase().replace(/[^a-z]/g, '')] = brandMap[k];
}
function buildNgrams(ts, maxN) {
  var out = [];
  for (var n = 1; n <= maxN; n++)
    for (var a0 = 0; a0 <= ts.length - n; a0++) {
      var parts = [];
      for (var b0 = 0; b0 < n; b0++) parts.push(ts[a0 + b0]);
      out.push(parts.join(' '));
    }
  return out;
}
var brands = [];
buildNgrams(tokensAll, 3).forEach(function(ng) {
  var ngKey = ng.toLowerCase().replace(/[^a-z]/g, '');
  var hit = brandKeyToCanonical[ngKey];
  if (hit && brands.indexOf(hit) === -1) brands.push(hit);
});

// 5) SKU / ProdNo detection
var codePattern = /^[a-z]{1,6}\d{2,6}[a-z0-9]*$/i;
var codes = [];
tokensAll.forEach(function(t) {
  if (codePattern.test(t)) {
    var up = String(t).toUpperCase();
    if (codes.indexOf(up) === -1) codes.push(up);
  }
});
var NOISE = { and:1, or:1, the:1, a:1, an:1, for:1, with:1, in:1, on:1, of:1, to:1 };
var onlyProdNo = false;
if (codes.length > 0) {
  onlyProdNo = true;
  for (i = 0; i < tokensAll.length; i++) {
    var tt = String(tokensAll[i]).toLowerCase();
    if (!/^[a-z0-9]+$/i.test(tt)) continue;
    if (codePattern.test(tt)) continue;
    if (NOISE[tt]) continue;
    if (tt.length <= 1) continue;
    onlyProdNo = false; break;
  }
}

// 6) Intent family detection
// Maps query terms to product category families for result gating
var FAM_SYNS = {
  headwear: ['hat','cap','caps','beanie','beanies','toque','knit cap','trucker','trucker hat','foam trucker','snapback','fitted','dad hat','visor','bucket','boonie','flat bill','mesh back','patch hat','5 panel','five panel'],
  tees: ['t-shirt','tee','tees','short sleeve tee','long sleeve tee','ringer','crewneck tee','pocket tee'],
  polos: ['polo','polos','golf shirt','golf polo','sport polo'],
  sweatshirts: ['hoodie','hoodies','hooded','pullover','zip hoodie','crewneck sweatshirt','sweatshirt','sweat shirt','fleece','quarter zip','1/4 zip','quarter-zip'],
  outerwear: ['jacket','jackets','shell','soft shell','softshell','windbreaker','rain jacket','parka','anorak','vest','vests','outerwear'],
  bags: ['bag','bags','backpack','backpacks','duffel','duffle','tote','totes','cinch sack','drawstring','waist pack','fanny pack','cooler','lunch bag'],
  bottoms: ['pants','trousers','shorts','joggers','sweatpants','leggings'],
  accessories: ['apron','aprons','blanket','blankets','gaiter','scarf','scarves','glove','gloves','socks','patch','patches']
};
var tokenSetAll = {};
tokensAll.forEach(function(t) { tokenSetAll[t] = 1; });
var qScan = ' ' + norm + ' ';
function hitPhrase(phrase) {
  var p = normalizeSpaces(phrase.toLowerCase());
  if (!p) return false;
  var esc = escapeRegex(p);
  if (p.indexOf(' ') === -1) {
    if (tokenSetAll[p]) return true;
    return new RegExp('(^|\\W)' + esc + '(?=\\W|$)', 'i').test(qScan);
  }
  return new RegExp('(^|\\W)' + esc + '(?=\\W|$)', 'i').test(qScan);
}
var intentFamiliesSet = {};
for (var fam in FAM_SYNS) {
  if (!Object.prototype.hasOwnProperty.call(FAM_SYNS, fam)) continue;
  FAM_SYNS[fam].forEach(function(syn) { if (hitPhrase(syn)) intentFamiliesSet[fam] = 1; });
}
var intentFamilies = Object.keys(intentFamiliesSet);

return [{ json: { q, tokens, brands, codes, onlyProdNo, page: 1, pageSize: 24, categories: categoryTerms, titleTerms, descTerms, intentFamilies } }];

/**
 * SKU / Product Code Extractor
 *
 * Extracts a structured product code from the query when one is present.
 * When found, sets onlyProdNo=true so the SKU route is taken instead of vector search.
 *
 * Handles: ST640, "ST 640", "st-640", GWT-SB, C112, C-112
 * Blocked: brand names like "cutter-buck", "sport-tek"
 * Phone numbers disambiguated by digit count heuristic.
 */

const CONFIG = {
  blockedAlphaDashPhrases: ['CUTTER-BUCK','CUTTER-AND-BUCK','CUTTER-&-BUCK','SPORT-TEK'],
  alphaDash:    { minTotalLen: 3, maxTotalLen: 15, re: /\b([A-Z]{2,6}(?:-[A-Z]{1,6})+)\b/ },
  alphaNumDash: { minTotalLen: 3, maxTotalLen: 15, re: /\b([A-Z0-9]+(?:-[A-Z0-9]+)*)\b/ },
  numericPair:  { re: /\b(\d{2,3})[- _./]?(\d{3,4})\b/ },
  contiguousDigits: { re: /\d{5,7}/ },
  tokenAlphaDash: { maxSegments: 3, maxSegmentLen: 4, maxTotalLen: 12 },
};

const toUpper = x => String(x ?? '').trim().toUpperCase();
const onlyDigits = s => String(s ?? '').replace(/\D+/g, '');
const isPhone = d => d.length === 7 || d.length === 10 || d.length === 11;
const phraseKey = s => toUpper(s).replace(/&/g,' AND ').replace(/[^A-Z0-9]+/g,' ').trim().replace(/\s+/g,'-');

const BLOCKED = new Set(CONFIG.blockedAlphaDashPhrases.map(phraseKey));
const isBlocked = (c, src='') => {
  const ck = phraseKey(c), sk = phraseKey(src);
  if (BLOCKED.has(ck)) return true;
  for (const bk of BLOCKED) if (sk.includes(bk) && bk.startsWith(ck)) return true;
  return false;
};

function firstMatch(S, re, validate) {
  const g = new RegExp(re.source, 'g'); let m;
  while ((m = g.exec(S)) !== null) {
    const c = toUpper(m[1] || m[0]);
    if (validate(c)) return c;
    if (g.lastIndex === m.index) g.lastIndex++;
  }
  return null;
}

function isSafeAlphaDashTokens(parts) {
  if (!Array.isArray(parts) || parts.length < 2) return false;
  if (parts.length > CONFIG.tokenAlphaDash.maxSegments) return false;
  const clean = parts.map(x => String(x ?? '').trim()).filter(Boolean);
  return clean.every(x => /^[A-Za-z]+$/.test(x) && x.length <= CONFIG.tokenAlphaDash.maxSegmentLen)
    && clean.join('-').length <= CONFIG.tokenAlphaDash.maxTotalLen;
}

function tryExtract(str, tokens) {
  const S = toUpper(str);
  if (!S) return null;
  const digits = onlyDigits(S), looksPhone = isPhone(digits);

  // Alpha-dash codes: GWT-SB
  const c0 = firstMatch(S, CONFIG.alphaDash.re, c =>
    c.length >= CONFIG.alphaDash.minTotalLen && c.length <= CONFIG.alphaDash.maxTotalLen && !isBlocked(c, S));
  if (c0) return c0;

  // Alphanumeric codes: ST640, C-112
  if (/[A-Z]/.test(S) && /\d/.test(S)) {
    const c1 = firstMatch(S, CONFIG.alphaNumDash.re, c =>
      c.length >= CONFIG.alphaNumDash.minTotalLen && c.length <= CONFIG.alphaNumDash.maxTotalLen
      && /[A-Z]/.test(c) && /\d/.test(c));
    if (c1) return c1;
  }

  // Numeric pair
  const m2 = S.match(CONFIG.numericPair.re);
  if (m2) {
    const [,a,b] = m2, hasDash = /-/.test(m2[0]), hasOther = /[ _./]/.test(m2[0]);
    return (hasDash || looksPhone || hasOther) ? `${a}-${b}` : `${a}${b}`;
  }

  // Contiguous digits
  const m3 = S.match(CONFIG.contiguousDigits.re);
  if (m3) {
    const d = m3[0];
    return (looksPhone && d.length === 7) ? `${d.slice(0,3)}-${d.slice(3)}` : d;
  }

  // Token fallback
  if (Array.isArray(tokens) && tokens.length >= 2) {
    const T = tokens.map(t => String(t ?? '').trim()).filter(Boolean);
    if (isSafeAlphaDashTokens(T)) {
      const joined = toUpper(T.join('-'));
      const md = joined.match(/^([A-Z]{1,4}(?:-[A-Z]{1,4})+)$/);
      if (md && !isBlocked(md[1], S)) return md[1];
    }
    if (/^\d{2,3}$/.test(T[0]) && /^\d{3,4}$/.test(T[1])) return `${T[0]}${T[1]}`;
    const letters = (T.find(x => /^[A-Za-z]{1,6}$/.test(x)) || '').toUpperCase();
    const digs    =  T.find(x => /^\d{1,6}$/.test(x)) || '';
    if (letters && digs) return `${letters}${digs}`;
  }

  return null;
}

return items.map(item => {
  const j = { ...(item.json || {}) };
  const rawQ = String(j.q ?? '').trim();
  const prodNo = tryExtract(rawQ, j.tokens);
  if (prodNo) {
    j.originalQ  = j.originalQ || rawQ;
    j.q          = prodNo;
    j.codes      = [...new Set([prodNo, ...(j.codes || [])])];
    j.onlyProdNo = true;
    j.tokens     = prodNo.includes('-') ? prodNo.split('-') : [prodNo];
  }
  return { json: j };
});

