-- Bulk pricing lookup using XML-based safe ingestion
-- This pattern avoids SQL injection on older SQL Server versions
-- that don't support table-valued parameters well from external drivers
DECLARE @ids TABLE (ProdNo NVARCHAR(50));
DECLARE @xml NVARCHAR(MAX) = N'{{ (() => {
  const arr = (($json.data || [])
    .map(d => (d.ProdNo?.[0] || '').toString().trim())
    .filter(s => s.length > 0));
  if (!arr.length) return '<root/>';
  const esc = s => s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  return '<root>' + arr.map(v => '<r>' + esc(v) + '</r>').join('') + '</root>';
})() }}';
INSERT INTO @ids (ProdNo)
SELECT DISTINCT n.value('.', 'NVARCHAR(50)')
FROM (SELECT CAST(@xml AS XML) AS x) AS T
CROSS APPLY T.x.nodes('/root/r') AS A(n);
SELECT p.*, pp.*
FROM your_db.dbo.Products p
JOIN your_db.dbo.ProductPrices pp ON p.ProductID = pp.ProductID
JOIN @ids i ON i.ProdNo = p.ProdNo;

DECLARE @ids TABLE (ProdNo NVARCHAR(50));
DECLARE @xml NVARCHAR(MAX) = N'{{ (() => {
  const arr = (($json.data || [])
    .map(d => (d.ProdNo?.[0] || '').toString().trim())
    .filter(s => s.length > 0));
  if (!arr.length) return '<root/>';
  const esc = s => s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  return '<root>' + arr.map(v => '<r>' + esc(v) + '</r>').join('') + '</root>';
})() }}';
INSERT INTO @ids (ProdNo)
SELECT DISTINCT n.value('.', 'NVARCHAR(50)')
FROM (SELECT CAST(@xml AS XML) AS x) AS T
CROSS APPLY T.x.nodes('/root/r') AS A(n);
SELECT p.*, pa.*
FROM your_db.dbo.Products p
JOIN your_db.dbo.ProductAttributes pa ON p.ProductID = pa.ProductID
JOIN @ids i ON i.ProdNo = p.ProdNo;
